{
  "name": "Nanonis扫描探针显微镜控制器",
  "name_en": "Nanonis scanning probe microscope controller",
  "manufacturer": "Nanonis",
  "description": "这是一类用于扫描探针显微镜实验的控制器与控制电子学设备，常见于扫描隧道显微镜和原子力显微镜平台。它用于连接主机与显微镜系统，执行实验控制、扫描过程协调以及测量数据交互，适合实验室中的自动化显微测量与仪器联动。",
  "description_en": "This is a controller and control-electronics unit used in scanning probe microscopy experiments, commonly paired with STM and AFM platforms. It connects the host computer to the microscope system and is used for experiment control, scan coordination, and measurement data exchange in automated laboratory microscopy workflows.",
  "tag_hints": [
    "scanning probe microscopy",
    "SPM controller",
    "STM control",
    "AFM control",
    "instrument control electronics",
    "TCP remote control"
  ],
  "actions": [
    {
      "action_name": "auto-make_header",
      "description": "构造发送到 Nanonis 控制器的 TCP 消息头。",
      "description_en": "Construct the TCP message header for a command sent to the Nanonis controller."
    },
    {
      "action_name": "auto-hex_to_int16",
      "description": "将 16 位十六进制数据转换为有符号整数。",
      "description_en": "Convert 16-bit hexadecimal data to a signed integer."
    },
    {
      "action_name": "auto-hex_to_uint16",
      "description": "将 16 位十六进制数据转换为无符号整数。",
      "description_en": "Convert 16-bit hexadecimal data to an unsigned integer."
    },
    {
      "action_name": "auto-hex_to_int32",
      "description": "将 32 位十六进制数据转换为有符号整数。",
      "description_en": "Convert 32-bit hexadecimal data to a signed integer."
    },
    {
      "action_name": "auto-hex_to_uint32",
      "description": "将 32 位十六进制数据转换为无符号整数。",
      "description_en": "Convert 32-bit hexadecimal data to an unsigned integer."
    },
    {
      "action_name": "auto-hex_to_float64",
      "description": "将 64 位十六进制数据转换为双精度浮点数。",
      "description_en": "Convert 64-bit hexadecimal data to a double-precision floating-point value."
    },
    {
      "action_name": "auto-hex_to_float32",
      "description": "将 32 位十六进制数据转换为单精度浮点数。",
      "description_en": "Convert 32-bit hexadecimal data to a single-precision floating-point value."
    },
    {
      "action_name": "auto-float64_to_hex",
      "description": "将双精度浮点数转换为 64 位十六进制数据。",
      "description_en": "Convert a double-precision floating-point value to 64-bit hexadecimal data."
    },
    {
      "action_name": "auto-float32_to_hex",
      "description": "将单精度浮点数转换为 32 位十六进制数据。",
      "description_en": "Convert a single-precision floating-point value to 32-bit hexadecimal data."
    },
    {
      "action_name": "auto-to_hex",
      "description": "按指定字节长度将数值编码为十六进制数据。",
      "description_en": "Encode a value as hexadecimal data with the specified byte length."
    },
    {
      "action_name": "auto-string_to_hex",
      "description": "将字符串编码为十六进制数据。",
      "description_en": "Encode a string as hexadecimal data."
    },
    {
      "action_name": "auto-send_command",
      "description": "向 Nanonis 控制器发送 TCP 命令消息。",
      "description_en": "Send a TCP command message to the Nanonis controller."
    },
    {
      "action_name": "auto-receive_response",
      "description": "接收 Nanonis 控制器返回的响应数据。",
      "description_en": "Receive the response data returned by the Nanonis controller."
    },
    {
      "action_name": "auto-check_error",
      "description": "检查控制器响应中的错误状态与错误信息。",
      "description_en": "Check the controller response for error status and error messages."
    },
    {
      "action_name": "auto-close_connection",
      "description": "关闭与 Nanonis 控制器的 TCP 连接。",
      "description_en": "Close the TCP connection to the Nanonis controller."
    }
  ]
}

